/* From Uiverse.io by gharsh11032000 - Tags: radio, radio-buttons, hover effect, click effect */
.__UIV_SCOPE__ .radio-buttons-container {
  display: flex;
  align-items: center;
  gap: 24px;
}

.__UIV_SCOPE__ .radio-button {
  display: inline-block;
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .radio-button__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .radio-button__label {
  display: inline-block;
  padding-left: 30px;
  margin-bottom: 10px;
  position: relative;
  font-size: 16px;
  color: #fff;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .radio-button__custom {
  position: absolute;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #555;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .radio-button__input:checked + .radio-button__label .radio-button__custom {
  transform: translateY(-50%) scale(0.9);
  border: 5px solid #4c8bf5;
  color: #4c8bf5;
}

.__UIV_SCOPE__ .radio-button__input:checked + .radio-button__label {
  color: #4c8bf5;
}

.__UIV_SCOPE__ .radio-button__label:hover .radio-button__custom {
  transform: translateY(-50%) scale(1.2);
  border-color: #4c8bf5;
  box-shadow: 0 0 10px #4c8bf580;
}
